1	int smb2_open(struct ksmbd_work *work)
2	{
3		struct ksmbd_conn *conn = work->conn;
4		struct ksmbd_session *sess = work->sess;
5		struct ksmbd_tree_connect *tcon = work->tcon;
6		struct smb2_create_req *req;
7		struct smb2_create_rsp *rsp;
8		struct path path, parent_path;
9		struct ksmbd_share_config *share = tcon->share_conf;
10		struct ksmbd_file *fp = NULL;
11		struct file *filp = NULL;
12		struct mnt_idmap *idmap = NULL;
13		struct kstat stat;
14		struct create_context *context;
15		struct lease_ctx_info *lc = NULL;
16		struct create_ea_buf_req *ea_buf = NULL;
17		struct oplock_info *opinfo;
18		struct durable_info dh_info = {0};
19		__le32 *next_ptr = NULL;
20		int req_op_level = 0, open_flags = 0, may_flags = 0, file_info = 0;
21		int rc = 0;
22		int contxt_cnt = 0, query_disk_id = 0;
23		int maximal_access_ctxt = 0, posix_ctxt = 0;
24		int s_type = 0;
25		int next_off = 0;
26		char *name = NULL;
27		char *stream_name = NULL;
28		bool file_present = false, created = false, already_permitted = false;
29		int share_ret, need_truncate = 0;
30		u64 time;
31		umode_t posix_mode = 0;
32		__le32 daccess, maximal_access = 0;
33		int iov_len = 0;
34	
35		WORK_BUFFERS(work, req, rsp);
36	
37		if (req->hdr.NextCommand && !work->next_smb2_rcv_hdr_off &&
38		    (req->hdr.Flags & SMB2_FLAGS_RELATED_OPERATIONS)) {
39			ksmbd_debug(SMB, "invalid flag in chained command\n");
40			rsp->hdr.Status = STATUS_INVALID_PARAMETER;
41			smb2_set_err_rsp(work);
42			return -EINVAL;
43		}
44	
45		if (test_share_config_flag(share, KSMBD_SHARE_FLAG_PIPE)) {
46			ksmbd_debug(SMB, "IPC pipe create request\n");
47			return create_smb2_pipe(work);
48		}
49	
50		if (req->NameLength) {
51			name = smb2_get_name((char *)req + le16_to_cpu(req->NameOffset),
52					     le16_to_cpu(req->NameLength),
53					     work->conn->local_nls);
54			if (IS_ERR(name)) {
55				rc = PTR_ERR(name);
56				name = NULL;
57				goto err_out2;
58			}
59	
60			ksmbd_debug(SMB, "converted name = %s\n", name);
61			if (strchr(name, ':')) {
62				if (!test_share_config_flag(work->tcon->share_conf,
63							    KSMBD_SHARE_FLAG_STREAMS)) {
64					rc = -EBADF;
65					goto err_out2;
66				}
67				rc = parse_stream_name(name, &stream_name, &s_type);
68				if (rc < 0)
69					goto err_out2;
70			}
71	
72			rc = ksmbd_validate_filename(name);
73			if (rc < 0)
74				goto err_out2;
75	
76			if (ksmbd_share_veto_filename(share, name)) {
77				rc = -ENOENT;
78				ksmbd_debug(SMB, "Reject open(), vetoed file: %s\n",
79					    name);
80				goto err_out2;
81			}
82		} else {
83			name = kstrdup("", GFP_KERNEL);
84			if (!name) {
85				rc = -ENOMEM;
86				goto err_out2;
87			}
88		}
89	
90		req_op_level = req->RequestedOplockLevel;
91	
92		if (server_conf.flags & KSMBD_GLOBAL_FLAG_DURABLE_HANDLE &&
93		    req->CreateContextsOffset) {
94			lc = parse_lease_state(req);
95			rc = parse_durable_handle_context(work, req, lc, &dh_info);
96			if (rc) {
97				ksmbd_debug(SMB, "error parsing durable handle context\n");
98				goto err_out2;
99			}
100	
101			if (dh_info.reconnected == true) {
102				rc = smb2_check_durable_oplock(conn, share, dh_info.fp, lc, name);
103				if (rc) {
104					ksmbd_put_durable_fd(dh_info.fp);
105					goto err_out2;
106				}
107	
108				rc = ksmbd_reopen_durable_fd(work, dh_info.fp);
109				if (rc) {
110					ksmbd_put_durable_fd(dh_info.fp);
111					goto err_out2;
112				}
113	
114				if (ksmbd_override_fsids(work)) {
115					rc = -ENOMEM;
116					ksmbd_put_durable_fd(dh_info.fp);
117					goto err_out2;
118				}
119	
120				fp = dh_info.fp;
121				file_info = FILE_OPENED;
122	
123				rc = ksmbd_vfs_getattr(&fp->filp->f_path, &stat);
124				if (rc)
125					goto err_out2;
126	
127				ksmbd_put_durable_fd(fp);
128				goto reconnected_fp;
129			}
130		} else if (req_op_level == SMB2_OPLOCK_LEVEL_LEASE)
131			lc = parse_lease_state(req);
132	
133		if (le32_to_cpu(req->ImpersonationLevel) > le32_to_cpu(IL_DELEGATE)) {
134			pr_err("Invalid impersonationlevel : 0x%x\n",
135			       le32_to_cpu(req->ImpersonationLevel));
136			rc = -EIO;
137			rsp->hdr.Status = STATUS_BAD_IMPERSONATION_LEVEL;
138			goto err_out2;
139		}
140	
141		if (req->CreateOptions && !(req->CreateOptions & CREATE_OPTIONS_MASK_LE)) {
142			pr_err("Invalid create options : 0x%x\n",
143			       le32_to_cpu(req->CreateOptions));
144			rc = -EINVAL;
145			goto err_out2;
146		} else {
147			if (req->CreateOptions & FILE_SEQUENTIAL_ONLY_LE &&
148			    req->CreateOptions & FILE_RANDOM_ACCESS_LE)
149				req->CreateOptions = ~(FILE_SEQUENTIAL_ONLY_LE);
150	
151			if (req->CreateOptions &
152			    (FILE_OPEN_BY_FILE_ID_LE | CREATE_TREE_CONNECTION |
153			     FILE_RESERVE_OPFILTER_LE)) {
154				rc = -EOPNOTSUPP;
155				goto err_out2;
156			}
157	
158			if (req->CreateOptions & FILE_DIRECTORY_FILE_LE) {
159				if (req->CreateOptions & FILE_NON_DIRECTORY_FILE_LE) {
160					rc = -EINVAL;
161					goto err_out2;
162				} else if (req->CreateOptions & FILE_NO_COMPRESSION_LE) {
163					req->CreateOptions = ~(FILE_NO_COMPRESSION_LE);
164				}
165			}
166		}
167	
168		if (le32_to_cpu(req->CreateDisposition) >
169		    le32_to_cpu(FILE_OVERWRITE_IF_LE)) {
170			pr_err("Invalid create disposition : 0x%x\n",
171			       le32_to_cpu(req->CreateDisposition));
172			rc = -EINVAL;
173			goto err_out2;
174		}
175	
176		if (!(req->DesiredAccess & DESIRED_ACCESS_MASK)) {
177			pr_err("Invalid desired access : 0x%x\n",
178			       le32_to_cpu(req->DesiredAccess));
179			rc = -EACCES;
180			goto err_out2;
181		}
182	
183		if (req->FileAttributes && !(req->FileAttributes & FILE_ATTRIBUTE_MASK_LE)) {
184			pr_err("Invalid file attribute : 0x%x\n",
185			       le32_to_cpu(req->FileAttributes));
186			rc = -EINVAL;
187			goto err_out2;
188		}
189	
190		if (req->CreateContextsOffset) {
191			/* Parse non-durable handle create contexts */
192			context = smb2_find_context_vals(req, SMB2_CREATE_EA_BUFFER, 4);
193			if (IS_ERR(context)) {
194				rc = PTR_ERR(context);
195				goto err_out2;
196			} else if (context) {
197				ea_buf = (struct create_ea_buf_req *)context;
198				if (le16_to_cpu(context->DataOffset) +
199				    le32_to_cpu(context->DataLength) <
200				    sizeof(struct create_ea_buf_req)) {
201					rc = -EINVAL;
202					goto err_out2;
203				}
204				if (req->CreateOptions & FILE_NO_EA_KNOWLEDGE_LE) {
205					rsp->hdr.Status = STATUS_ACCESS_DENIED;
206					rc = -EACCES;
207					goto err_out2;
208				}
209			}
210	
211			context = smb2_find_context_vals(req,
212							 SMB2_CREATE_QUERY_MAXIMAL_ACCESS_REQUEST, 4);
213			if (IS_ERR(context)) {
214				rc = PTR_ERR(context);
215				goto err_out2;
216			} else if (context) {
217				ksmbd_debug(SMB,
218					    "get query maximal access context\n");
219				maximal_access_ctxt = 1;
220			}
221	
222			context = smb2_find_context_vals(req,
223							 SMB2_CREATE_TIMEWARP_REQUEST, 4);
224			if (IS_ERR(context)) {
225				rc = PTR_ERR(context);
226				goto err_out2;
227			} else if (context) {
228				ksmbd_debug(SMB, "get timewarp context\n");
229				rc = -EBADF;
230				goto err_out2;
231			}
232	
233			if (tcon->posix_extensions) {
234				context = smb2_find_context_vals(req,
235								 SMB2_CREATE_TAG_POSIX, 16);
236				if (IS_ERR(context)) {
237					rc = PTR_ERR(context);
238					goto err_out2;
239				} else if (context) {
240					struct create_posix *posix =
241						(struct create_posix *)context;
242					if (le16_to_cpu(context->DataOffset) +
243					    le32_to_cpu(context->DataLength) <
244					    sizeof(struct create_posix) - 4) {
245						rc = -EINVAL;
246						goto err_out2;
247					}
248					ksmbd_debug(SMB, "get posix context\n");
249	
250					posix_mode = le32_to_cpu(posix->Mode);
251					posix_ctxt = 1;
252				}
253			}
254		}
255	
256		if (ksmbd_override_fsids(work)) {
257			rc = -ENOMEM;
258			goto err_out2;
259		}
260	
261		rc = ksmbd_vfs_kern_path_locked(work, name, LOOKUP_NO_SYMLINKS,
262						&parent_path, &path, 1);
263		if (!rc) {
264			file_present = true;
265	
266			if (req->CreateOptions & FILE_DELETE_ON_CLOSE_LE) {
267				/*
268				 * If file exists with under flags, return access
269				 * denied error.
270				 */
271				if (req->CreateDisposition == FILE_OVERWRITE_IF_LE ||
272				    req->CreateDisposition == FILE_OPEN_IF_LE) {
273					rc = -EACCES;
274					goto err_out;
275				}
276	
277				if (!test_tree_conn_flag(tcon, KSMBD_TREE_CONN_FLAG_WRITABLE)) {
278					ksmbd_debug(SMB,
279						    "User does not have write permission\n");
280					rc = -EACCES;
281					goto err_out;
282				}
283			} else if (d_is_symlink(path.dentry)) {
284				rc = -EACCES;
285				goto err_out;
286			}
287	
288			file_present = true;
289			idmap = mnt_idmap(path.mnt);
290		} else {
291			if (rc != -ENOENT)
292				goto err_out;
293			ksmbd_debug(SMB, "can not get linux path for %s, rc = %d\n",
294				    name, rc);
295			rc = 0;
296		}
297	
298		if (stream_name) {
299			if (req->CreateOptions & FILE_DIRECTORY_FILE_LE) {
300				if (s_type == DATA_STREAM) {
301					rc = -EIO;
302					rsp->hdr.Status = STATUS_NOT_A_DIRECTORY;
303				}
304			} else {
305				if (file_present && S_ISDIR(d_inode(path.dentry)->i_mode) &&
306				    s_type == DATA_STREAM) {
307					rc = -EIO;
308					rsp->hdr.Status = STATUS_FILE_IS_A_DIRECTORY;
309				}
310			}
311	
312			if (req->CreateOptions & FILE_DIRECTORY_FILE_LE &&
313			    req->FileAttributes & FILE_ATTRIBUTE_NORMAL_LE) {
314				rsp->hdr.Status = STATUS_NOT_A_DIRECTORY;
315				rc = -EIO;
316			}
317	
318			if (rc < 0)
319				goto err_out;
320		}
321	
322		if (file_present && req->CreateOptions & FILE_NON_DIRECTORY_FILE_LE &&
323		    S_ISDIR(d_inode(path.dentry)->i_mode) &&
324		    !(req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)) {
325			ksmbd_debug(SMB, "open() argument is a directory: %s, %x\n",
326				    name, req->CreateOptions);
327			rsp->hdr.Status = STATUS_FILE_IS_A_DIRECTORY;
328			rc = -EIO;
329			goto err_out;
330		}
331	
332		if (file_present && (req->CreateOptions & FILE_DIRECTORY_FILE_LE) &&
333		    !(req->CreateDisposition == FILE_CREATE_LE) &&
334		    !S_ISDIR(d_inode(path.dentry)->i_mode)) {
335			rsp->hdr.Status = STATUS_NOT_A_DIRECTORY;
336			rc = -EIO;
337			goto err_out;
338		}
339	
340		if (!stream_name && file_present &&
341		    req->CreateDisposition == FILE_CREATE_LE) {
342			rc = -EEXIST;
343			goto err_out;
344		}
345	
346		daccess = smb_map_generic_desired_access(req->DesiredAccess);
347	
348		if (file_present && !(req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)) {
349			rc = smb_check_perm_dacl(conn, &path, &daccess,
350						 sess->user->uid);
351			if (rc)
352				goto err_out;
353		}
354	
355		if (daccess & FILE_MAXIMAL_ACCESS_LE) {
356			if (!file_present) {
357				daccess = cpu_to_le32(GENERIC_ALL_FLAGS);
358			} else {
359				ksmbd_vfs_query_maximal_access(idmap,
360								    path.dentry,
361								    &daccess);
362				already_permitted = true;
363			}
364			maximal_access = daccess;
365		}
366	
367		open_flags = smb2_create_open_flags(file_present, daccess,
368						    req->CreateDisposition,
369						    &may_flags,
370			req->CreateOptions & FILE_DIRECTORY_FILE_LE ||
371			(file_present && S_ISDIR(d_inode(path.dentry)->i_mode)));
372	
373		if (!test_tree_conn_flag(tcon, KSMBD_TREE_CONN_FLAG_WRITABLE)) {
374			if (open_flags & (O_CREAT | O_TRUNC)) {
375				ksmbd_debug(SMB,
376					    "User does not have write permission\n");
377				rc = -EACCES;
378				goto err_out;
379			}
380		}
381	
382		/*create file if not present */
383		if (!file_present) {
384			rc = smb2_creat(work, &parent_path, &path, name, open_flags,
385					posix_mode,
386					req->CreateOptions & FILE_DIRECTORY_FILE_LE);
387			if (rc) {
388				if (rc == -ENOENT) {
389					rc = -EIO;
390					rsp->hdr.Status = STATUS_OBJECT_PATH_NOT_FOUND;
391				}
392				goto err_out;
393			}
394	
395			created = true;
396			idmap = mnt_idmap(path.mnt);
397			if (ea_buf) {
398				if (le32_to_cpu(ea_buf->ccontext.DataLength) <
399				    sizeof(struct smb2_ea_info)) {
400					rc = -EINVAL;
401					goto err_out;
402				}
403	
404				rc = smb2_set_ea(&ea_buf->ea,
405						 le32_to_cpu(ea_buf->ccontext.DataLength),
406						 &path, false);
407				if (rc == -EOPNOTSUPP)
408					rc = 0;
409				else if (rc)
410					goto err_out;
411			}
412		} else if (!already_permitted) {
413			/* FILE_READ_ATTRIBUTE is allowed without inode_permission,
414			 * because execute(search) permission on a parent directory,
415			 * is already granted.
416			 */
417			if (daccess & ~(FILE_READ_ATTRIBUTES_LE | FILE_READ_CONTROL_LE)) {
418				rc = inode_permission(idmap,
419						      d_inode(path.dentry),
420						      may_flags);
421				if (rc)
422					goto err_out;
423	
424				if ((daccess & FILE_DELETE_LE) ||
425				    (req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)) {
426					rc = inode_permission(idmap,
427							      d_inode(path.dentry->d_parent),
428							      MAY_EXEC | MAY_WRITE);
429					if (rc)
430						goto err_out;
431				}
432			}
433		}
434	
435		rc = ksmbd_query_inode_status(path.dentry->d_parent);
436		if (rc == KSMBD_INODE_STATUS_PENDING_DELETE) {
437			rc = -EBUSY;
438			goto err_out;
439		}
440	
441		rc = 0;
442		filp = dentry_open(&path, open_flags, current_cred());
443		if (IS_ERR(filp)) {
444			rc = PTR_ERR(filp);
445			pr_err("dentry open for dir failed, rc %d\n", rc);
446			goto err_out;
447		}
448	
449		if (file_present) {
450			if (!(open_flags & O_TRUNC))
451				file_info = FILE_OPENED;
452			else
453				file_info = FILE_OVERWRITTEN;
454	
455			if ((req->CreateDisposition & FILE_CREATE_MASK_LE) ==
456			    FILE_SUPERSEDE_LE)
457				file_info = FILE_SUPERSEDED;
458		} else if (open_flags & O_CREAT) {
459			file_info = FILE_CREATED;
460		}
461	
462		ksmbd_vfs_set_fadvise(filp, req->CreateOptions);
463	
464		/* Obtain Volatile-ID */
465		fp = ksmbd_open_fd(work, filp);
466		if (IS_ERR(fp)) {
467			fput(filp);
468			rc = PTR_ERR(fp);
469			fp = NULL;
470			goto err_out;
471		}
472	
473		/* Get Persistent-ID */
474		ksmbd_open_durable_fd(fp);
475		if (!has_file_id(fp->persistent_id)) {
476			rc = -ENOMEM;
477			goto err_out;
478		}
479	
480		fp->cdoption = req->CreateDisposition;
481		fp->daccess = daccess;
482		fp->saccess = req->ShareAccess;
483		fp->coption = req->CreateOptions;
484	
485		/* Set default windows and posix acls if creating new file */
486		if (created) {
487			int posix_acl_rc;
488			struct inode *inode = d_inode(path.dentry);
489	
490			posix_acl_rc = ksmbd_vfs_inherit_posix_acl(idmap,
491								   &path,
492								   d_inode(path.dentry->d_parent));
493			if (posix_acl_rc)
494				ksmbd_debug(SMB, "inherit posix acl failed : %d\n", posix_acl_rc);
495	
496			if (test_share_config_flag(work->tcon->share_conf,
497						   KSMBD_SHARE_FLAG_ACL_XATTR)) {
498				rc = smb_inherit_dacl(conn, &path, sess->user->uid,
499						      sess->user->gid);
500			}
501	
502			if (rc) {
503				rc = smb2_create_sd_buffer(work, req, &path);
504				if (rc) {
505					if (posix_acl_rc)
506						ksmbd_vfs_set_init_posix_acl(idmap,
507									     &path);
508	
509					if (test_share_config_flag(work->tcon->share_conf,
510								   KSMBD_SHARE_FLAG_ACL_XATTR)) {
511						struct smb_fattr fattr;
512						struct smb_ntsd *pntsd;
513						int pntsd_size, ace_num = 0;
514	
515						ksmbd_acls_fattr(&fattr, idmap, inode);
516						if (fattr.cf_acls)
517							ace_num = fattr.cf_acls->a_count;
518						if (fattr.cf_dacls)
519							ace_num += fattr.cf_dacls->a_count;
520	
521						pntsd = kmalloc(sizeof(struct smb_ntsd) +
522								sizeof(struct smb_sid) * 3 +
523								sizeof(struct smb_acl) +
524								sizeof(struct smb_ace) * ace_num * 2,
525								GFP_KERNEL);
526						if (!pntsd) {
527							posix_acl_release(fattr.cf_acls);
528							posix_acl_release(fattr.cf_dacls);
529							goto err_out;
530						}
531	
532						rc = build_sec_desc(idmap,
533								    pntsd, NULL, 0,
534								    OWNER_SECINFO |
535								    GROUP_SECINFO |
536								    DACL_SECINFO,
537								    &pntsd_size, &fattr);
538						posix_acl_release(fattr.cf_acls);
539						posix_acl_release(fattr.cf_dacls);
540						if (rc) {
541							kfree(pntsd);
542							goto err_out;
543						}
544	
545						rc = ksmbd_vfs_set_sd_xattr(conn,
546									    idmap,
547									    &path,
548									    pntsd,
549									    pntsd_size,
550									    false);
551						kfree(pntsd);
552						if (rc)
553							pr_err("failed to store ntacl in xattr : %d\n",
554							       rc);
555					}
556				}
557			}
558			rc = 0;
559		}
560	
561		if (stream_name) {
562			rc = smb2_set_stream_name_xattr(&path,
563							fp,
564							stream_name,
565							s_type);
566			if (rc)
567				goto err_out;
568			file_info = FILE_CREATED;
569		}
570	
571		fp->attrib_only = !(req->DesiredAccess & ~(FILE_READ_ATTRIBUTES_LE |
572				FILE_WRITE_ATTRIBUTES_LE | FILE_SYNCHRONIZE_LE));
573	
574		/* fp should be searchable through ksmbd_inode.m_fp_list
575		 * after daccess, saccess, attrib_only, and stream are
576		 * initialized.
577		 */
578		down_write(&fp->f_ci->m_lock);
579		list_add(&fp->node, &fp->f_ci->m_fp_list);
580		up_write(&fp->f_ci->m_lock);
581	
582		/* Check delete pending among previous fp before oplock break */
583		if (ksmbd_inode_pending_delete(fp)) {
584			rc = -EBUSY;
585			goto err_out;
586		}
587	
588		if (file_present || created)
589			ksmbd_vfs_kern_path_unlock(&parent_path, &path);
590	
591		if (!S_ISDIR(file_inode(filp)->i_mode) && open_flags & O_TRUNC &&
592		    !fp->attrib_only && !stream_name) {
593			smb_break_all_oplock(work, fp);
594			need_truncate = 1;
595		}
596	
597		share_ret = ksmbd_smb_check_shared_mode(fp->filp, fp);
598		if (!test_share_config_flag(work->tcon->share_conf, KSMBD_SHARE_FLAG_OPLOCKS) ||
599		    (req_op_level == SMB2_OPLOCK_LEVEL_LEASE &&
600		     !(conn->vals->capabilities & SMB2_GLOBAL_CAP_LEASING))) {
601			if (share_ret < 0 && !S_ISDIR(file_inode(fp->filp)->i_mode)) {
602				rc = share_ret;
603				goto err_out1;
604			}
605		} else {
606			if (req_op_level == SMB2_OPLOCK_LEVEL_LEASE && lc) {
607				if (S_ISDIR(file_inode(filp)->i_mode)) {
608					lc->req_state &= ~SMB2_LEASE_WRITE_CACHING_LE;
609					lc->is_dir = true;
610				}
611	
612				/*
613				 * Compare parent lease using parent key. If there is no
614				 * a lease that has same parent key, Send lease break
615				 * notification.
616				 */
617				smb_send_parent_lease_break_noti(fp, lc);
618	
619				req_op_level = smb2_map_lease_to_oplock(lc->req_state);
620				ksmbd_debug(SMB,
621					    "lease req for(%s) req oplock state 0x%x, lease state 0x%x\n",
622					    name, req_op_level, lc->req_state);
623				rc = find_same_lease_key(sess, fp->f_ci, lc);
624				if (rc)
625					goto err_out1;
626			} else if (open_flags == O_RDONLY &&
627				   (req_op_level == SMB2_OPLOCK_LEVEL_BATCH ||
628				    req_op_level == SMB2_OPLOCK_LEVEL_EXCLUSIVE))
629				req_op_level = SMB2_OPLOCK_LEVEL_II;
630	
631			rc = smb_grant_oplock(work, req_op_level,
632					      fp->persistent_id, fp,
633					      le32_to_cpu(req->hdr.Id.SyncId.TreeId),
634					      lc, share_ret);
635			if (rc < 0)
636				goto err_out1;
637		}
638	
639		if (req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)
640			ksmbd_fd_set_delete_on_close(fp, file_info);
641	
642		if (need_truncate) {
643			rc = smb2_create_truncate(&fp->filp->f_path);
644			if (rc)
645				goto err_out1;
646		}
647	
648		if (req->CreateContextsOffset) {
649			struct create_alloc_size_req *az_req;
650	
651			az_req = (struct create_alloc_size_req *)smb2_find_context_vals(req,
652						SMB2_CREATE_ALLOCATION_SIZE, 4);
653			if (IS_ERR(az_req)) {
654				rc = PTR_ERR(az_req);
655				goto err_out1;
656			} else if (az_req) {
657				loff_t alloc_size;
658				int err;
659	
660				if (le16_to_cpu(az_req->ccontext.DataOffset) +
661				    le32_to_cpu(az_req->ccontext.DataLength) <
662				    sizeof(struct create_alloc_size_req)) {
663					rc = -EINVAL;
664					goto err_out1;
665				}
666				alloc_size = le64_to_cpu(az_req->AllocationSize);
667				ksmbd_debug(SMB,
668					    "request smb2 create allocate size : %llu\n",
669					    alloc_size);
670				smb_break_all_levII_oplock(work, fp, 1);
671				err = vfs_fallocate(fp->filp, FALLOC_FL_KEEP_SIZE, 0,
672						    alloc_size);
673				if (err < 0)
674					ksmbd_debug(SMB,
675						    "vfs_fallocate is failed : %d\n",
676						    err);
677			}
678	
679			context = smb2_find_context_vals(req, SMB2_CREATE_QUERY_ON_DISK_ID, 4);
680			if (IS_ERR(context)) {
681				rc = PTR_ERR(context);
682				goto err_out1;
683			} else if (context) {
684				ksmbd_debug(SMB, "get query on disk id context\n");
685				query_disk_id = 1;
686			}
687		}
688	
689		rc = ksmbd_vfs_getattr(&path, &stat);
690		if (rc)
691			goto err_out1;
692	
693		if (stat.result_mask & STATX_BTIME)
694			fp->create_time = ksmbd_UnixTimeToNT(stat.btime);
695		else
696			fp->create_time = ksmbd_UnixTimeToNT(stat.ctime);
697		if (req->FileAttributes || fp->f_ci->m_fattr == 0)
698			fp->f_ci->m_fattr =
699				cpu_to_le32(smb2_get_dos_mode(&stat, le32_to_cpu(req->FileAttributes)));
700	
701		if (!created)
702			smb2_update_xattrs(tcon, &path, fp);
703		else
704			smb2_new_xattrs(tcon, &path, fp);
705	
706		memcpy(fp->client_guid, conn->ClientGUID, SMB2_CLIENT_GUID_SIZE);
707	
708		if (dh_info.type == DURABLE_REQ_V2 || dh_info.type == DURABLE_REQ) {
709			if (dh_info.type == DURABLE_REQ_V2 && dh_info.persistent &&
710			    test_share_config_flag(work->tcon->share_conf,
711						   KSMBD_SHARE_FLAG_CONTINUOUS_AVAILABILITY))
712				fp->is_persistent = true;
713			else
714				fp->is_durable = true;
715	
716			if (dh_info.type == DURABLE_REQ_V2) {
717				memcpy(fp->create_guid, dh_info.CreateGuid,
718						SMB2_CREATE_GUID_SIZE);
719				if (dh_info.timeout)
720					fp->durable_timeout = min(dh_info.timeout,
721							DURABLE_HANDLE_MAX_TIMEOUT);
722				else
723					fp->durable_timeout = 60;
724			}
725		}
726	
727	reconnected_fp:
728		rsp->StructureSize = cpu_to_le16(89);
729		rcu_read_lock();
730		opinfo = rcu_dereference(fp->f_opinfo);
731		rsp->OplockLevel = opinfo != NULL ? opinfo->level : 0;
732		rcu_read_unlock();
733		rsp->Flags = 0;
734		rsp->CreateAction = cpu_to_le32(file_info);
735		rsp->CreationTime = cpu_to_le64(fp->create_time);
736		time = ksmbd_UnixTimeToNT(stat.atime);
737		rsp->LastAccessTime = cpu_to_le64(time);
738		time = ksmbd_UnixTimeToNT(stat.mtime);
739		rsp->LastWriteTime = cpu_to_le64(time);
740		time = ksmbd_UnixTimeToNT(stat.ctime);
741		rsp->ChangeTime = cpu_to_le64(time);
742		rsp->AllocationSize = S_ISDIR(stat.mode) ? 0 :
743			cpu_to_le64(stat.blocks << 9);
744		rsp->EndofFile = S_ISDIR(stat.mode) ? 0 : cpu_to_le64(stat.size);
745		rsp->FileAttributes = fp->f_ci->m_fattr;
746	
747		rsp->Reserved2 = 0;
748	
749		rsp->PersistentFileId = fp->persistent_id;
750		rsp->VolatileFileId = fp->volatile_id;
751	
752		rsp->CreateContextsOffset = 0;
753		rsp->CreateContextsLength = 0;
754		iov_len = offsetof(struct smb2_create_rsp, Buffer);
755	
756		/* If lease is request send lease context response */
757		if (opinfo && opinfo->is_lease) {
758			struct create_context *lease_ccontext;
759	
760			ksmbd_debug(SMB, "lease granted on(%s) lease state 0x%x\n",
761				    name, opinfo->o_lease->state);
762			rsp->OplockLevel = SMB2_OPLOCK_LEVEL_LEASE;
763	
764			lease_ccontext = (struct create_context *)rsp->Buffer;
765			contxt_cnt++;
766			create_lease_buf(rsp->Buffer, opinfo->o_lease);
767			le32_add_cpu(&rsp->CreateContextsLength,
768				     conn->vals->create_lease_size);
769			iov_len += conn->vals->create_lease_size;
770			next_ptr = &lease_ccontext->Next;
771			next_off = conn->vals->create_lease_size;
772		}
773	
774		if (maximal_access_ctxt) {
775			struct create_context *mxac_ccontext;
776	
777			if (maximal_access == 0)
778				ksmbd_vfs_query_maximal_access(idmap,
779							       path.dentry,
780							       &maximal_access);
781			mxac_ccontext = (struct create_context *)(rsp->Buffer +
782					le32_to_cpu(rsp->CreateContextsLength));
783			contxt_cnt++;
784			create_mxac_rsp_buf(rsp->Buffer +
785					le32_to_cpu(rsp->CreateContextsLength),
786					le32_to_cpu(maximal_access));
787			le32_add_cpu(&rsp->CreateContextsLength,
788				     conn->vals->create_mxac_size);
789			iov_len += conn->vals->create_mxac_size;
790			if (next_ptr)
791				*next_ptr = cpu_to_le32(next_off);
792			next_ptr = &mxac_ccontext->Next;
793			next_off = conn->vals->create_mxac_size;
794		}
795	
796		if (query_disk_id) {
797			struct create_context *disk_id_ccontext;
798	
799			disk_id_ccontext = (struct create_context *)(rsp->Buffer +
800					le32_to_cpu(rsp->CreateContextsLength));
801			contxt_cnt++;
802			create_disk_id_rsp_buf(rsp->Buffer +
803					le32_to_cpu(rsp->CreateContextsLength),
804					stat.ino, tcon->id);
805			le32_add_cpu(&rsp->CreateContextsLength,
806				     conn->vals->create_disk_id_size);
807			iov_len += conn->vals->create_disk_id_size;
808			if (next_ptr)
809				*next_ptr = cpu_to_le32(next_off);
810			next_ptr = &disk_id_ccontext->Next;
811			next_off = conn->vals->create_disk_id_size;
812		}
813	
814		if (dh_info.type == DURABLE_REQ || dh_info.type == DURABLE_REQ_V2) {
815			struct create_context *durable_ccontext;
816	
817			durable_ccontext = (struct create_context *)(rsp->Buffer +
818					le32_to_cpu(rsp->CreateContextsLength));
819			contxt_cnt++;
820			if (dh_info.type == DURABLE_REQ) {
821				create_durable_rsp_buf(rsp->Buffer +
822						le32_to_cpu(rsp->CreateContextsLength));
823				le32_add_cpu(&rsp->CreateContextsLength,
824						conn->vals->create_durable_size);
825				iov_len += conn->vals->create_durable_size;
826			} else {
827				create_durable_v2_rsp_buf(rsp->Buffer +
828						le32_to_cpu(rsp->CreateContextsLength),
829						fp);
830				le32_add_cpu(&rsp->CreateContextsLength,
831						conn->vals->create_durable_v2_size);
832				iov_len += conn->vals->create_durable_v2_size;
833			}
834	
835			if (next_ptr)
836				*next_ptr = cpu_to_le32(next_off);
837			next_ptr = &durable_ccontext->Next;
838			next_off = conn->vals->create_durable_size;
839		}
840	
841		if (posix_ctxt) {
842			contxt_cnt++;
843			create_posix_rsp_buf(rsp->Buffer +
844					le32_to_cpu(rsp->CreateContextsLength),
845					fp);
846			le32_add_cpu(&rsp->CreateContextsLength,
847				     conn->vals->create_posix_size);
848			iov_len += conn->vals->create_posix_size;
849			if (next_ptr)
850				*next_ptr = cpu_to_le32(next_off);
851		}
852	
853		if (contxt_cnt > 0) {
854			rsp->CreateContextsOffset =
855				cpu_to_le32(offsetof(struct smb2_create_rsp, Buffer));
856		}
857	
858	err_out:
859		if (rc && (file_present || created))
860			ksmbd_vfs_kern_path_unlock(&parent_path, &path);
861	
862	err_out1:
863		ksmbd_revert_fsids(work);
864	
865	err_out2:
866		if (!rc) {
867			ksmbd_update_fstate(&work->sess->file_table, fp, FP_INITED);
868			rc = ksmbd_iov_pin_rsp(work, (void *)rsp, iov_len);
869		}
870		if (rc) {
871			if (rc == -EINVAL)
872				rsp->hdr.Status = STATUS_INVALID_PARAMETER;
873			else if (rc == -EOPNOTSUPP)
874				rsp->hdr.Status = STATUS_NOT_SUPPORTED;
875			else if (rc == -EACCES || rc == -ESTALE || rc == -EXDEV)
876				rsp->hdr.Status = STATUS_ACCESS_DENIED;
877			else if (rc == -ENOENT)
878				rsp->hdr.Status = STATUS_OBJECT_NAME_INVALID;
879			else if (rc == -EPERM)
880				rsp->hdr.Status = STATUS_SHARING_VIOLATION;
881			else if (rc == -EBUSY)
882				rsp->hdr.Status = STATUS_DELETE_PENDING;
883			else if (rc == -EBADF)
884				rsp->hdr.Status = STATUS_OBJECT_NAME_NOT_FOUND;
885			else if (rc == -ENOEXEC)
886				rsp->hdr.Status = STATUS_DUPLICATE_OBJECTID;
887			else if (rc == -ENXIO)
888				rsp->hdr.Status = STATUS_NO_SUCH_DEVICE;
889			else if (rc == -EEXIST)
890				rsp->hdr.Status = STATUS_OBJECT_NAME_COLLISION;
891			else if (rc == -EMFILE)
892				rsp->hdr.Status = STATUS_INSUFFICIENT_RESOURCES;
893			if (!rsp->hdr.Status)
894				rsp->hdr.Status = STATUS_UNEXPECTED_IO_ERROR;
895	
896			if (fp)
897				ksmbd_fd_put(work, fp);
898			smb2_set_err_rsp(work);
899			ksmbd_debug(SMB, "Error response: %x\n", rsp->hdr.Status);
900		}
901	
902		kfree(name);
903		kfree(lc);
904	
905		return rc;
906	}
907

file.content:
int smb2_open(struct ksmbd_work *work)
{
	struct ksmbd_conn *conn = work->conn;
	struct ksmbd_session *sess = work->sess;
	struct ksmbd_tree_connect *tcon = work->tcon;
	struct smb2_create_req *req;
	struct smb2_create_rsp *rsp;
	struct path path, parent_path;
	struct ksmbd_share_config *share = tcon->share_conf;
	struct ksmbd_file *fp = NULL;
	struct file *filp = NULL;
	struct mnt_idmap *idmap = NULL;
	struct kstat stat;
	struct create_context *context;
	struct lease_ctx_info *lc = NULL;
	struct create_ea_buf_req *ea_buf = NULL;
	struct oplock_info *opinfo;
	struct durable_info dh_info = {0};
	__le32 *next_ptr = NULL;
	int req_op_level = 0, open_flags = 0, may_flags = 0, file_info = 0;
	int rc = 0;
	int contxt_cnt = 0, query_disk_id = 0;
	int maximal_access_ctxt = 0, posix_ctxt = 0;
	int s_type = 0;
	int next_off = 0;
	char *name = NULL;
	char *stream_name = NULL;
	bool file_present = false, created = false, already_permitted = false;
	int share_ret, need_truncate = 0;
	u64 time;
	umode_t posix_mode = 0;
	__le32 daccess, maximal_access = 0;
	int iov_len = 0;

	WORK_BUFFERS(work, req, rsp);

	if (req->hdr.NextCommand && !work->next_smb2_rcv_hdr_off &&
	    (req->hdr.Flags & SMB2_FLAGS_RELATED_OPERATIONS)) {
		ksmbd_debug(SMB, "invalid flag in chained command\n");
		rsp->hdr.Status = STATUS_INVALID_PARAMETER;
		smb2_set_err_rsp(work);
		return -EINVAL;
	}

	if (test_share_config_flag(share, KSMBD_SHARE_FLAG_PIPE)) {
		ksmbd_debug(SMB, "IPC pipe create request\n");
		return create_smb2_pipe(work);
	}

	if (req->NameLength) {
		name = smb2_get_name((char *)req + le16_to_cpu(req->NameOffset),
				     le16_to_cpu(req->NameLength),
				     work->conn->local_nls);
		if (IS_ERR(name)) {
			rc = PTR_ERR(name);
			name = NULL;
			goto err_out2;
		}

		ksmbd_debug(SMB, "converted name = %s\n", name);
		if (strchr(name, ':')) {
			if (!test_share_config_flag(work->tcon->share_conf,
						    KSMBD_SHARE_FLAG_STREAMS)) {
				rc = -EBADF;
				goto err_out2;
			}
			rc = parse_stream_name(name, &stream_name, &s_type);
			if (rc < 0)
				goto err_out2;
		}

		rc = ksmbd_validate_filename(name);
		if (rc < 0)
			goto err_out2;

		if (ksmbd_share_veto_filename(share, name)) {
			rc = -ENOENT;
			ksmbd_debug(SMB, "Reject open(), vetoed file: %s\n",
				    name);
			goto err_out2;
		}
	} else {
		name = kstrdup("", GFP_KERNEL);
		if (!name) {
			rc = -ENOMEM;
			goto err_out2;
		}
	}

	req_op_level = req->RequestedOplockLevel;

	if (server_conf.flags & KSMBD_GLOBAL_FLAG_DURABLE_HANDLE &&
	    req->CreateContextsOffset) {
		lc = parse_lease_state(req);
		rc = parse_durable_handle_context(work, req, lc, &dh_info);
		if (rc) {
			ksmbd_debug(SMB, "error parsing durable handle context\n");
			goto err_out2;
		}

		if (dh_info.reconnected == true) {
			rc = smb2_check_durable_oplock(conn, share, dh_info.fp, lc, name);
			if (rc) {
				ksmbd_put_durable_fd(dh_info.fp);
				goto err_out2;
			}

			rc = ksmbd_reopen_durable_fd(work, dh_info.fp);
			if (rc) {
				ksmbd_put_durable_fd(dh_info.fp);
				goto err_out2;
			}

			if (ksmbd_override_fsids(work)) {
				rc = -ENOMEM;
				ksmbd_put_durable_fd(dh_info.fp);
				goto err_out2;
			}

			fp = dh_info.fp;
			file_info = FILE_OPENED;

			rc = ksmbd_vfs_getattr(&fp->filp->f_path, &stat);
			if (rc)
				goto err_out2;

			ksmbd_put_durable_fd(fp);
			goto reconnected_fp;
		}
	} else if (req_op_level == SMB2_OPLOCK_LEVEL_LEASE)
		lc = parse_lease_state(req);

	if (le32_to_cpu(req->ImpersonationLevel) > le32_to_cpu(IL_DELEGATE)) {
		pr_err("Invalid impersonationlevel : 0x%x\n",
		       le32_to_cpu(req->ImpersonationLevel));
		rc = -EIO;
		rsp->hdr.Status = STATUS_BAD_IMPERSONATION_LEVEL;
		goto err_out2;
	}

	if (req->CreateOptions && !(req->CreateOptions & CREATE_OPTIONS_MASK_LE)) {
		pr_err("Invalid create options : 0x%x\n",
		       le32_to_cpu(req->CreateOptions));
		rc = -EINVAL;
		goto err_out2;
	} else {
		if (req->CreateOptions & FILE_SEQUENTIAL_ONLY_LE &&
		    req->CreateOptions & FILE_RANDOM_ACCESS_LE)
			req->CreateOptions = ~(FILE_SEQUENTIAL_ONLY_LE);

		if (req->CreateOptions &
		    (FILE_OPEN_BY_FILE_ID_LE | CREATE_TREE_CONNECTION |
		     FILE_RESERVE_OPFILTER_LE)) {
			rc = -EOPNOTSUPP;
			goto err_out2;
		}

		if (req->CreateOptions & FILE_DIRECTORY_FILE_LE) {
			if (req->CreateOptions & FILE_NON_DIRECTORY_FILE_LE) {
				rc = -EINVAL;
				goto err_out2;
			} else if (req->CreateOptions & FILE_NO_COMPRESSION_LE) {
				req->CreateOptions = ~(FILE_NO_COMPRESSION_LE);
			}
		}
	}

	if (le32_to_cpu(req->CreateDisposition) >
	    le32_to_cpu(FILE_OVERWRITE_IF_LE)) {
		pr_err("Invalid create disposition : 0x%x\n",
		       le32_to_cpu(req->CreateDisposition));
		rc = -EINVAL;
		goto err_out2;
	}

	if (!(req->DesiredAccess & DESIRED_ACCESS_MASK)) {
		pr_err("Invalid desired access : 0x%x\n",
		       le32_to_cpu(req->DesiredAccess));
		rc = -EACCES;
		goto err_out2;
	}

	if (req->FileAttributes && !(req->FileAttributes & FILE_ATTRIBUTE_MASK_LE)) {
		pr_err("Invalid file attribute : 0x%x\n",
		       le32_to_cpu(req->FileAttributes));
		rc = -EINVAL;
		goto err_out2;
	}

	if (req->CreateContextsOffset) {
		/* Parse non-durable handle create contexts */
		context = smb2_find_context_vals(req, SMB2_CREATE_EA_BUFFER, 4);
		if (IS_ERR(context)) {
			rc = PTR_ERR(context);
			goto err_out2;
		} else if (context) {
			ea_buf = (struct create_ea_buf_req *)context;
			if (le16_to_cpu(context->DataOffset) +
			    le32_to_cpu(context->DataLength) <
			    sizeof(struct create_ea_buf_req)) {
				rc = -EINVAL;
				goto err_out2;
			}
			if (req->CreateOptions & FILE_NO_EA_KNOWLEDGE_LE) {
				rsp->hdr.Status = STATUS_ACCESS_DENIED;
				rc = -EACCES;
				goto err_out2;
			}
		}

		context = smb2_find_context_vals(req,
						 SMB2_CREATE_QUERY_MAXIMAL_ACCESS_REQUEST, 4);
		if (IS_ERR(context)) {
			rc = PTR_ERR(context);
			goto err_out2;
		} else if (context) {
			ksmbd_debug(SMB,
				    "get query maximal access context\n");
			maximal_access_ctxt = 1;
		}

		context = smb2_find_context_vals(req,
						 SMB2_CREATE_TIMEWARP_REQUEST, 4);
		if (IS_ERR(context)) {
			rc = PTR_ERR(context);
			goto err_out2;
		} else if (context) {
			ksmbd_debug(SMB, "get timewarp context\n");
			rc = -EBADF;
			goto err_out2;
		}

		if (tcon->posix_extensions) {
			context = smb2_find_context_vals(req,
							 SMB2_CREATE_TAG_POSIX, 16);
			if (IS_ERR(context)) {
				rc = PTR_ERR(context);
				goto err_out2;
			} else if (context) {
				struct create_posix *posix =
					(struct create_posix *)context;
				if (le16_to_cpu(context->DataOffset) +
				    le32_to_cpu(context->DataLength) <
				    sizeof(struct create_posix) - 4) {
					rc = -EINVAL;
					goto err_out2;
				}
				ksmbd_debug(SMB, "get posix context\n");

				posix_mode = le32_to_cpu(posix->Mode);
				posix_ctxt = 1;
			}
		}
	}

	if (ksmbd_override_fsids(work)) {
		rc = -ENOMEM;
		goto err_out2;
	}

	rc = ksmbd_vfs_kern_path_locked(work, name, LOOKUP_NO_SYMLINKS,
					&parent_path, &path, 1);
	if (!rc) {
		file_present = true;

		if (req->CreateOptions & FILE_DELETE_ON_CLOSE_LE) {
			/*
			 * If file exists with under flags, return access
			 * denied error.
			 */
			if (req->CreateDisposition == FILE_OVERWRITE_IF_LE ||
			    req->CreateDisposition == FILE_OPEN_IF_LE) {
				rc = -EACCES;
				goto err_out;
			}

			if (!test_tree_conn_flag(tcon, KSMBD_TREE_CONN_FLAG_WRITABLE)) {
				ksmbd_debug(SMB,
					    "User does not have write permission\n");
				rc = -EACCES;
				goto err_out;
			}
		} else if (d_is_symlink(path.dentry)) {
			rc = -EACCES;
			goto err_out;
		}

		file_present = true;
		idmap = mnt_idmap(path.mnt);
	} else {
		if (rc != -ENOENT)
			goto err_out;
		ksmbd_debug(SMB, "can not get linux path for %s, rc = %d\n",
			    name, rc);
		rc = 0;
	}

	if (stream_name) {
		if (req->CreateOptions & FILE_DIRECTORY_FILE_LE) {
			if (s_type == DATA_STREAM) {
				rc = -EIO;
				rsp->hdr.Status = STATUS_NOT_A_DIRECTORY;
			}
		} else {
			if (file_present && S_ISDIR(d_inode(path.dentry)->i_mode) &&
			    s_type == DATA_STREAM) {
				rc = -EIO;
				rsp->hdr.Status = STATUS_FILE_IS_A_DIRECTORY;
			}
		}

		if (req->CreateOptions & FILE_DIRECTORY_FILE_LE &&
		    req->FileAttributes & FILE_ATTRIBUTE_NORMAL_LE) {
			rsp->hdr.Status = STATUS_NOT_A_DIRECTORY;
			rc = -EIO;
		}

		if (rc < 0)
			goto err_out;
	}

	if (file_present && req->CreateOptions & FILE_NON_DIRECTORY_FILE_LE &&
	    S_ISDIR(d_inode(path.dentry)->i_mode) &&
	    !(req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)) {
		ksmbd_debug(SMB, "open() argument is a directory: %s, %x\n",
			    name, req->CreateOptions);
		rsp->hdr.Status = STATUS_FILE_IS_A_DIRECTORY;
		rc = -EIO;
		goto err_out;
	}

	if (file_present && (req->CreateOptions & FILE_DIRECTORY_FILE_LE) &&
	    !(req->CreateDisposition == FILE_CREATE_LE) &&
	    !S_ISDIR(d_inode(path.dentry)->i_mode)) {
		rsp->hdr.Status = STATUS_NOT_A_DIRECTORY;
		rc = -EIO;
		goto err_out;
	}

	if (!stream_name && file_present &&
	    req->CreateDisposition == FILE_CREATE_LE) {
		rc = -EEXIST;
		goto err_out;
	}

	daccess = smb_map_generic_desired_access(req->DesiredAccess);

	if (file_present && !(req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)) {
		rc = smb_check_perm_dacl(conn, &path, &daccess,
					 sess->user->uid);
		if (rc)
			goto err_out;
	}

	if (daccess & FILE_MAXIMAL_ACCESS_LE) {
		if (!file_present) {
			daccess = cpu_to_le32(GENERIC_ALL_FLAGS);
		} else {
			ksmbd_vfs_query_maximal_access(idmap,
							    path.dentry,
							    &daccess);
			already_permitted = true;
		}
		maximal_access = daccess;
	}

	open_flags = smb2_create_open_flags(file_present, daccess,
					    req->CreateDisposition,
					    &may_flags,
		req->CreateOptions & FILE_DIRECTORY_FILE_LE ||
		(file_present && S_ISDIR(d_inode(path.dentry)->i_mode)));

	if (!test_tree_conn_flag(tcon, KSMBD_TREE_CONN_FLAG_WRITABLE)) {
		if (open_flags & (O_CREAT | O_TRUNC)) {
			ksmbd_debug(SMB,
				    "User does not have write permission\n");
			rc = -EACCES;
			goto err_out;
		}
	}

	/*create file if not present */
	if (!file_present) {
		rc = smb2_creat(work, &parent_path, &path, name, open_flags,
				posix_mode,
				req->CreateOptions & FILE_DIRECTORY_FILE_LE);
		if (rc) {
			if (rc == -ENOENT) {
				rc = -EIO;
				rsp->hdr.Status = STATUS_OBJECT_PATH_NOT_FOUND;
			}
			goto err_out;
		}

		created = true;
		idmap = mnt_idmap(path.mnt);
		if (ea_buf) {
			if (le32_to_cpu(ea_buf->ccontext.DataLength) <
			    sizeof(struct smb2_ea_info)) {
				rc = -EINVAL;
				goto err_out;
			}

			rc = smb2_set_ea(&ea_buf->ea,
					 le32_to_cpu(ea_buf->ccontext.DataLength),
					 &path, false);
			if (rc == -EOPNOTSUPP)
				rc = 0;
			else if (rc)
				goto err_out;
		}
	} else if (!already_permitted) {
		/* FILE_READ_ATTRIBUTE is allowed without inode_permission,
		 * because execute(search) permission on a parent directory,
		 * is already granted.
		 */
		if (daccess & ~(FILE_READ_ATTRIBUTES_LE | FILE_READ_CONTROL_LE)) {
			rc = inode_permission(idmap,
					      d_inode(path.dentry),
					      may_flags);
			if (rc)
				goto err_out;

			if ((daccess & FILE_DELETE_LE) ||
			    (req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)) {
				rc = inode_permission(idmap,
						      d_inode(path.dentry->d_parent),
						      MAY_EXEC | MAY_WRITE);
				if (rc)
					goto err_out;
			}
		}
	}

	rc = ksmbd_query_inode_status(path.dentry->d_parent);
	if (rc == KSMBD_INODE_STATUS_PENDING_DELETE) {
		rc = -EBUSY;
		goto err_out;
	}

	rc = 0;
	filp = dentry_open(&path, open_flags, current_cred());
	if (IS_ERR(filp)) {
		rc = PTR_ERR(filp);
		pr_err("dentry open for dir failed, rc %d\n", rc);
		goto err_out;
	}

	if (file_present) {
		if (!(open_flags & O_TRUNC))
			file_info = FILE_OPENED;
		else
			file_info = FILE_OVERWRITTEN;

		if ((req->CreateDisposition & FILE_CREATE_MASK_LE) ==
		    FILE_SUPERSEDE_LE)
			file_info = FILE_SUPERSEDED;
	} else if (open_flags & O_CREAT) {
		file_info = FILE_CREATED;
	}

	ksmbd_vfs_set_fadvise(filp, req->CreateOptions);

	/* Obtain Volatile-ID */
	fp = ksmbd_open_fd(work, filp);
	if (IS_ERR(fp)) {
		fput(filp);
		rc = PTR_ERR(fp);
		fp = NULL;
		goto err_out;
	}

	/* Get Persistent-ID */
	ksmbd_open_durable_fd(fp);
	if (!has_file_id(fp->persistent_id)) {
		rc = -ENOMEM;
		goto err_out;
	}

	fp->cdoption = req->CreateDisposition;
	fp->daccess = daccess;
	fp->saccess = req->ShareAccess;
	fp->coption = req->CreateOptions;

	/* Set default windows and posix acls if creating new file */
	if (created) {
		int posix_acl_rc;
		struct inode *inode = d_inode(path.dentry);

		posix_acl_rc = ksmbd_vfs_inherit_posix_acl(idmap,
							   &path,
							   d_inode(path.dentry->d_parent));
		if (posix_acl_rc)
			ksmbd_debug(SMB, "inherit posix acl failed : %d\n", posix_acl_rc);

		if (test_share_config_flag(work->tcon->share_conf,
					   KSMBD_SHARE_FLAG_ACL_XATTR)) {
			rc = smb_inherit_dacl(conn, &path, sess->user->uid,
					      sess->user->gid);
		}

		if (rc) {
			rc = smb2_create_sd_buffer(work, req, &path);
			if (rc) {
				if (posix_acl_rc)
					ksmbd_vfs_set_init_posix_acl(idmap,
								     &path);

				if (test_share_config_flag(work->tcon->share_conf,
							   KSMBD_SHARE_FLAG_ACL_XATTR)) {
					struct smb_fattr fattr;
					struct smb_ntsd *pntsd;
					int pntsd_size, ace_num = 0;

					ksmbd_acls_fattr(&fattr, idmap, inode);
					if (fattr.cf_acls)
						ace_num = fattr.cf_acls->a_count;
					if (fattr.cf_dacls)
						ace_num += fattr.cf_dacls->a_count;

					pntsd = kmalloc(sizeof(struct smb_ntsd) +
							sizeof(struct smb_sid) * 3 +
							sizeof(struct smb_acl) +
							sizeof(struct smb_ace) * ace_num * 2,
							GFP_KERNEL);
					if (!pntsd) {
						posix_acl_release(fattr.cf_acls);
						posix_acl_release(fattr.cf_dacls);
						goto err_out;
					}

					rc = build_sec_desc(idmap,
							    pntsd, NULL, 0,
							    OWNER_SECINFO |
							    GROUP_SECINFO |
							    DACL_SECINFO,
							    &pntsd_size, &fattr);
					posix_acl_release(fattr.cf_acls);
					posix_acl_release(fattr.cf_dacls);
					if (rc) {
						kfree(pntsd);
						goto err_out;
					}

					rc = ksmbd_vfs_set_sd_xattr(conn,
								    idmap,
								    &path,
								    pntsd,
								    pntsd_size,
								    false);
					kfree(pntsd);
					if (rc)
						pr_err("failed to store ntacl in xattr : %d\n",
						       rc);
				}
			}
		}
		rc = 0;
	}

	if (stream_name) {
		rc = smb2_set_stream_name_xattr(&path,
						fp,
						stream_name,
						s_type);
		if (rc)
			goto err_out;
		file_info = FILE_CREATED;
	}

	fp->attrib_only = !(req->DesiredAccess & ~(FILE_READ_ATTRIBUTES_LE |
			FILE_WRITE_ATTRIBUTES_LE | FILE_SYNCHRONIZE_LE));

	/* fp should be searchable through ksmbd_inode.m_fp_list
	 * after daccess, saccess, attrib_only, and stream are
	 * initialized.
	 */
	down_write(&fp->f_ci->m_lock);
	list_add(&fp->node, &fp->f_ci->m_fp_list);
	up_write(&fp->f_ci->m_lock);

	/* Check delete pending among previous fp before oplock break */
	if (ksmbd_inode_pending_delete(fp)) {
		rc = -EBUSY;
		goto err_out;
	}

	if (file_present || created)
		ksmbd_vfs_kern_path_unlock(&parent_path, &path);

	if (!S_ISDIR(file_inode(filp)->i_mode) && open_flags & O_TRUNC &&
	    !fp->attrib_only && !stream_name) {
		smb_break_all_oplock(work, fp);
		need_truncate = 1;
	}

	share_ret = ksmbd_smb_check_shared_mode(fp->filp, fp);
	if (!test_share_config_flag(work->tcon->share_conf, KSMBD_SHARE_FLAG_OPLOCKS) ||
	    (req_op_level == SMB2_OPLOCK_LEVEL_LEASE &&
	     !(conn->vals->capabilities & SMB2_GLOBAL_CAP_LEASING))) {
		if (share_ret < 0 && !S_ISDIR(file_inode(fp->filp)->i_mode)) {
			rc = share_ret;
			goto err_out1;
		}
	} else {
		if (req_op_level == SMB2_OPLOCK_LEVEL_LEASE && lc) {
			if (S_ISDIR(file_inode(filp)->i_mode)) {
				lc->req_state &= ~SMB2_LEASE_WRITE_CACHING_LE;
				lc->is_dir = true;
			}

			/*
			 * Compare parent lease using parent key. If there is no
			 * a lease that has same parent key, Send lease break
			 * notification.
			 */
			smb_send_parent_lease_break_noti(fp, lc);

			req_op_level = smb2_map_lease_to_oplock(lc->req_state);
			ksmbd_debug(SMB,
				    "lease req for(%s) req oplock state 0x%x, lease state 0x%x\n",
				    name, req_op_level, lc->req_state);
			rc = find_same_lease_key(sess, fp->f_ci, lc);
			if (rc)
				goto err_out1;
		} else if (open_flags == O_RDONLY &&
			   (req_op_level == SMB2_OPLOCK_LEVEL_BATCH ||
			    req_op_level == SMB2_OPLOCK_LEVEL_EXCLUSIVE))
			req_op_level = SMB2_OPLOCK_LEVEL_II;

		rc = smb_grant_oplock(work, req_op_level,
				      fp->persistent_id, fp,
				      le32_to_cpu(req->hdr.Id.SyncId.TreeId),
				      lc, share_ret);
		if (rc < 0)
			goto err_out1;
	}

	if (req->CreateOptions & FILE_DELETE_ON_CLOSE_LE)
		ksmbd_fd_set_delete_on_close(fp, file_info);

	if (need_truncate) {
		rc = smb2_create_truncate(&fp->filp->f_path);
		if (rc)
			goto err_out1;
	}

	if (req->CreateContextsOffset) {
		struct create_alloc_size_req *az_req;

		az_req = (struct create_alloc_size_req *)smb2_find_context_vals(req,
					SMB2_CREATE_ALLOCATION_SIZE, 4);
		if (IS_ERR(az_req)) {
			rc = PTR_ERR(az_req);
			goto err_out1;
		} else if (az_req) {
			loff_t alloc_size;
			int err;

			if (le16_to_cpu(az_req->ccontext.DataOffset) +
			    le32_to_cpu(az_req->ccontext.DataLength) <
			    sizeof(struct create_alloc_size_req)) {
				rc = -EINVAL;
				goto err_out1;
			}
			alloc_size = le64_to_cpu(az_req->AllocationSize);
			ksmbd_debug(SMB,
				    "request smb2 create allocate size : %llu\n",
				    alloc_size);
			smb_break_all_levII_oplock(work, fp, 1);
			err = vfs_fallocate(fp->filp, FALLOC_FL_KEEP_SIZE, 0,
					    alloc_size);
			if (err < 0)
				ksmbd_debug(SMB,
					    "vfs_fallocate is failed : %d\n",
					    err);
		}

		context = smb2_find_context_vals(req, SMB2_CREATE_QUERY_ON_DISK_ID, 4);
		if (IS_ERR(context)) {
			rc = PTR_ERR(context);
			goto err_out1;
		} else if (context) {
			ksmbd_debug(SMB, "get query on disk id context\n");
			query_disk_id = 1;
		}
	}

	rc = ksmbd_vfs_getattr(&path, &stat);
	if (rc)
		goto err_out1;

	if (stat.result_mask & STATX_BTIME)
		fp->create_time = ksmbd_UnixTimeToNT(stat.btime);
	else
		fp->create_time = ksmbd_UnixTimeToNT(stat.ctime);
	if (req->FileAttributes || fp->f_ci->m_fattr == 0)
		fp->f_ci->m_fattr =
			cpu_to_le32(smb2_get_dos_mode(&stat, le32_to_cpu(req->FileAttributes)));

	if (!created)
		smb2_update_xattrs(tcon, &path, fp);
	else
		smb2_new_xattrs(tcon, &path, fp);

	memcpy(fp->client_guid, conn->ClientGUID, SMB2_CLIENT_GUID_SIZE);

	if (dh_info.type == DURABLE_REQ_V2 || dh_info.type == DURABLE_REQ) {
		if (dh_info.type == DURABLE_REQ_V2 && dh_info.persistent &&
		    test_share_config_flag(work->tcon->share_conf,
					   KSMBD_SHARE_FLAG_CONTINUOUS_AVAILABILITY))
			fp->is_persistent = true;
		else
			fp->is_durable = true;

		if (dh_info.type == DURABLE_REQ_V2) {
			memcpy(fp->create_guid, dh_info.CreateGuid,
					SMB2_CREATE_GUID_SIZE);
			if (dh_info.timeout)
				fp->durable_timeout = min(dh_info.timeout,
						DURABLE_HANDLE_MAX_TIMEOUT);
			else
				fp->durable_timeout = 60;
		}
	}

reconnected_fp:
	rsp->StructureSize = cpu_to_le16(89);
	rcu_read_lock();
	opinfo = rcu_dereference(fp->f_opinfo);
	rsp->OplockLevel = opinfo != NULL ? opinfo->level : 0;
	rcu_read_unlock();
	rsp->Flags = 0;
	rsp->CreateAction = cpu_to_le32(file_info);
	rsp->CreationTime = cpu_to_le64(fp->create_time);
	time = ksmbd_UnixTimeToNT(stat.atime);
	rsp->LastAccessTime = cpu_to_le64(time);
	time = ksmbd_UnixTimeToNT(stat.mtime);
	rsp->LastWriteTime = cpu_to_le64(time);
	time = ksmbd_UnixTimeToNT(stat.ctime);
	rsp->ChangeTime = cpu_to_le64(time);
	rsp->AllocationSize = S_ISDIR(stat.mode) ? 0 :
		cpu_to_le64(stat.blocks << 9);
	rsp->EndofFile = S_ISDIR(stat.mode) ? 0 : cpu_to_le64(stat.size);
	rsp->FileAttributes = fp->f_ci->m_fattr;

	rsp->Reserved2 = 0;

	rsp->PersistentFileId = fp->persistent_id;
	rsp->VolatileFileId = fp->volatile_id;

	rsp->CreateContextsOffset = 0;
	rsp->CreateContextsLength = 0;
	iov_len = offsetof(struct smb2_create_rsp, Buffer);

	/* If lease is request send lease context response */
	if (opinfo && opinfo->is_lease) {
		struct create_context *lease_ccontext;

		ksmbd_debug(SMB, "lease granted on(%s) lease state 0x%x\n",
			    name, opinfo->o_lease->state);
		rsp->OplockLevel = SMB2_OPLOCK_LEVEL_LEASE;

		lease_ccontext = (struct create_context *)rsp->Buffer;
		contxt_cnt++;
		create_lease_buf(rsp->Buffer, opinfo->o_lease);
		le32_add_cpu(&rsp->CreateContextsLength,
			     conn->vals->create_lease_size);
		iov_len += conn->vals->create_lease_size;
		next_ptr = &lease_ccontext->Next;
		next_off = conn->vals->create_lease_size;
	}

	if (maximal_access_ctxt) {
		struct create_context *mxac_ccontext;

		if (maximal_access == 0)
			ksmbd_vfs_query_maximal_access(idmap,
						       path.dentry,
						       &maximal_access);
		mxac_ccontext = (struct create_context *)(rsp->Buffer +
				le32_to_cpu(rsp->CreateContextsLength));
		contxt_cnt++;
		create_mxac_rsp_buf(rsp->Buffer +
				le32_to_cpu(rsp->CreateContextsLength),
				le32_to_cpu(maximal_access));
		le32_add_cpu(&rsp->CreateContextsLength,
			     conn->vals->create_mxac_size);
		iov_len += conn->vals->create_mxac_size;
		if (next_ptr)
			*next_ptr = cpu_to_le32(next_off);
		next_ptr = &mxac_ccontext->Next;
		next_off = conn->vals->create_mxac_size;
	}

	if (query_disk_id) {
		struct create_context *disk_id_ccontext;

		disk_id_ccontext = (struct create_context *)(rsp->Buffer +
				le32_to_cpu(rsp->CreateContextsLength));
		contxt_cnt++;
		create_disk_id_rsp_buf(rsp->Buffer +
				le32_to_cpu(rsp->CreateContextsLength),
				stat.ino, tcon->id);
		le32_add_cpu(&rsp->CreateContextsLength,
			     conn->vals->create_disk_id_size);
		iov_len += conn->vals->create_disk_id_size;
		if (next_ptr)
			*next_ptr = cpu_to_le32(next_off);
		next_ptr = &disk_id_ccontext->Next;
		next_off = conn->vals->create_disk_id_size;
	}

	if (dh_info.type == DURABLE_REQ || dh_info.type == DURABLE_REQ_V2) {
		struct create_context *durable_ccontext;

		durable_ccontext = (struct create_context *)(rsp->Buffer +
				le32_to_cpu(rsp->CreateContextsLength));
		contxt_cnt++;
		if (dh_info.type == DURABLE_REQ) {
			create_durable_rsp_buf(rsp->Buffer +
					le32_to_cpu(rsp->CreateContextsLength));
			le32_add_cpu(&rsp->CreateContextsLength,
					conn->vals->create_durable_size);
			iov_len += conn->vals->create_durable_size;
		} else {
			create_durable_v2_rsp_buf(rsp->Buffer +
					le32_to_cpu(rsp->CreateContextsLength),
					fp);
			le32_add_cpu(&rsp->CreateContextsLength,
					conn->vals->create_durable_v2_size);
			iov_len += conn->vals->create_durable_v2_size;
		}

		if (next_ptr)
			*next_ptr = cpu_to_le32(next_off);
		next_ptr = &durable_ccontext->Next;
		next_off = conn->vals->create_durable_size;
	}

	if (posix_ctxt) {
		contxt_cnt++;
		create_posix_rsp_buf(rsp->Buffer +
				le32_to_cpu(rsp->CreateContextsLength),
				fp);
		le32_add_cpu(&rsp->CreateContextsLength,
			     conn->vals->create_posix_size);
		iov_len += conn->vals->create_posix_size;
		if (next_ptr)
			*next_ptr = cpu_to_le32(next_off);
	}

	if (contxt_cnt > 0) {
		rsp->CreateContextsOffset =
			cpu_to_le32(offsetof(struct smb2_create_rsp, Buffer));
	}

err_out:
	if (rc && (file_present || created))
		ksmbd_vfs_kern_path_unlock(&parent_path, &path);

err_out1:
	ksmbd_revert_fsids(work);

err_out2:
	if (!rc) {
		ksmbd_update_fstate(&work->sess->file_table, fp, FP_INITED);
		rc = ksmbd_iov_pin_rsp(work, (void *)rsp, iov_len);
	}
	if (rc) {
		if (rc == -EINVAL)
			rsp->hdr.Status = STATUS_INVALID_PARAMETER;
		else if (rc == -EOPNOTSUPP)
			rsp->hdr.Status = STATUS_NOT_SUPPORTED;
		else if (rc == -EACCES || rc == -ESTALE || rc == -EXDEV)
			rsp->hdr.Status = STATUS_ACCESS_DENIED;
		else if (rc == -ENOENT)
			rsp->hdr.Status = STATUS_OBJECT_NAME_INVALID;
		else if (rc == -EPERM)
			rsp->hdr.Status = STATUS_SHARING_VIOLATION;
		else if (rc == -EBUSY)
			rsp->hdr.Status = STATUS_DELETE_PENDING;
		else if (rc == -EBADF)
			rsp->hdr.Status = STATUS_OBJECT_NAME_NOT_FOUND;
		else if (rc == -ENOEXEC)
			rsp->hdr.Status = STATUS_DUPLICATE_OBJECTID;
		else if (rc == -ENXIO)
			rsp->hdr.Status = STATUS_NO_SUCH_DEVICE;
		else if (rc == -EEXIST)
			rsp->hdr.Status = STATUS_OBJECT_NAME_COLLISION;
		else if (rc == -EMFILE)
			rsp->hdr.Status = STATUS_INSUFFICIENT_RESOURCES;
		if (!rsp->hdr.Status)
			rsp->hdr.Status = STATUS_UNEXPECTED_IO_ERROR;

		if (fp)
			ksmbd_fd_put(work, fp);
		smb2_set_err_rsp(work);
		ksmbd_debug(SMB, "Error response: %x\n", rsp->hdr.Status);
	}

	kfree(name);
	kfree(lc);

	return rc;
}

